<script lang="ts">
  import {onMount} from 'svelte';type Passkey={id:string;friendly_name:string};let passkeys=$state<Passkey[]>([]);let signingOut=$state(false);let error=$state('');let loading=$state(true);
  onMount(async()=>{try{const response=await fetch('/account/passkeys',{credentials:'same-origin'});if(response.status===401){window.location.assign('/');return;}if(!response.ok)throw new Error();passkeys=await response.json();}catch{error='We could not load your security settings.';}finally{loading=false;}});
  async function rename(passkey:Passkey){const friendly_name=window.prompt('New passkey name',passkey.friendly_name)?.trim();if(!friendly_name)return;const response=await fetch(`/account/passkeys/${passkey.id}`,{method:'PATCH',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({friendly_name})});if(response.ok)passkey.friendly_name=friendly_name;else error='Fresh sign-in is required to change this passkey.';}
  async function remove(passkey:Passkey){if(!window.confirm(`Remove “${passkey.friendly_name}”? You cannot undo this.`))return;const response=await fetch(`/account/passkeys/${passkey.id}`,{method:'DELETE',credentials:'same-origin'});if(response.ok)passkeys=passkeys.filter((value)=>value.id!==passkey.id);else error='Keep at least one sign-in method and sign in again before removing a passkey.';}
  async function logout(){signingOut=true;const response=await fetch('/session/logout',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'}});if(response.ok)window.location.assign('/');else{error='We could not sign out. Please try again.';signingOut=false;}}
</script>
<svelte:head><title>Account security · Piquel</title></svelte:head><section><p class="eyebrow">Piquel account</p><h1>Account security</h1>{#if error}<div class="error" role="alert">{error}</div>{/if}<div class="card"><h2>Passkeys</h2>{#if loading}<p role="status">Loading passkeys…</p>{:else if passkeys.length}<ul>{#each passkeys as passkey}<li><span>{passkey.friendly_name}</span><span><button class="secondary compact" onclick={()=>rename(passkey)}>Rename</button> <button class="danger compact" onclick={()=>remove(passkey)}>Remove</button></span></li>{/each}</ul>{:else}<p>No passkeys were returned.</p>{/if}<a class="provider" href="/register">Add a passkey</a><p class="help">Changes require a sign-in from the last ten minutes.</p></div><div class="card"><h2>Social sign-in</h2><p>GitHub and Google identities are linked by stable provider identity, never by email alone.</p></div><button class="secondary" onclick={logout} disabled={signingOut}>{signingOut?'Signing out…':'Sign out'}</button></section><style>ul{list-style:none;padding:0;display:grid;gap:.6rem}li{display:flex;align-items:center;justify-content:space-between;gap:1rem}.compact{min-height:2rem;padding:.45rem .7rem}.danger{background:#8b2929}</style>
